/**
 * Translates a single text phrase, checking exact dictionary match first, then pattern rules.
 * Returns the translated Russian string if matched, or undefined if unchanged.
 */
export function translatePhrase(text: string): string | undefined {
  if (!text || typeof text !== 'string') return undefined
  const trimmed = text.trim()
  if (!trimmed) return undefined

  // 1. Exact match
  if (PHRASE_MAP_RU[trimmed]) {
    const res = PHRASE_MAP_RU[trimmed]
    // Preserve surrounding whitespace if any
    if (text !== trimmed) {
      const leading = text.match(/^\s*/)?.[0] || ''
      const trailing = text.match(/\s*$/)?.[0] || ''
      return leading + res + trailing
    }
    return res
  }

  // 2. Pattern matching
  for (const [pattern, replacer] of REGEX_RULES) {
    if (pattern.test(trimmed)) {
      const res = typeof replacer === 'string'
        ? trimmed.replace(pattern, replacer)
        : trimmed.replace(pattern, replacer as any)
      if (text !== trimmed) {
        const leading = text.match(/^\s*/)?.[0] || ''
        const trailing = text.match(/\s*$/)?.[0] || ''
        return leading + res + trailing
      }
      return res
    }
  }

  return undefined
}
